    budget = getattr(sandbox, 'FORCE_BUDGET_PER_STEP', 12000.0)
    particles = sandbox.get_fluid_particles()
    if not particles:
        return

    # Assume particle mass based on radius and density
    particle_radius = 0.1
    particle_density = 1000  # kg/m³
    particle_mass = (4.0 / 3.0) * math.pi * (particle_radius ** 3) * particle_density
    g = 10.0  # m/s²
    used = 0.0

    def get_prio(p):
        x, y = p.position.x, p.position.y
        # Priority: 0 = gravity well, 1 = Pit3, 2 = source, 3 = build zone, 4 = target
        if 10.0 <= x <= 14.0 and 1.5 <= y <= 3.5:
            return 0  # Gravity well is highest priority
        elif 11.0 <= x <= 12.5 and y <= 1.6:
            return 1  # Pit3 is next priority
        elif x < 6.0 and y < 1.5:
            return 2  # Source area
        elif 6.0 <= x <= 18.0:
            return 3  # Build zone
        else:
            return 4  # Target zone

    # Sort particles by priority (0 = highest, so we reverse the sort)
    particles.sort(key=get_prio)

    for p in particles:
        if used >= budget:
            break
        x, y = p.position.x, p.position.y
        vx, vy = p.linearVelocity.x, p.linearVelocity.y
        fx, fy = 0.0, 0.0

        # Gravity well region: apply vertical force to escape
        if 10.0 <= x <= 14.0 and 1.5 <= y <= 3.5:
            target_vy = 4.0  # Lift to y=4.0 to clear gravity well
            fy = particle_mass * (30.0 * (target_vy - vy) - g)  # Increased vertical acceleration
            # Horizontal force to move toward build zone
            if x < 10.0:
                target_vx = 6.0  # Push left
            elif x > 14.0:
                target_vx = 18.0  # Push right
            else:
                target_vx = 12.0  # Push toward center
            fx = particle_mass * 10.0 * (target_vx - vx)  # Reduced horizontal acceleration

        # Pit3 region: apply vertical and horizontal force to escape
        elif 11.0 <= x <= 12.5 and y <= 1.6:
            target_vy = 4.0  # Lift to y=4.0 to clear Pit3
            fy = particle_mass * (10.0 * (target_vy - vy) - g)  # Reduced vertical acceleration
            # Horizontal force to push away from Pit3
            if x < 11.5:
                target_vx = 13.5  # Push right to bypass Pit3
            else:
                target_vx = 11.5  # Push left to bypass Pit3
            fx = particle_mass * 15.0 * (target_vx - vx)  # Increased horizontal acceleration

        # Source area: push horizontally and vertically to avoid Pit3
        elif x < 6.0 and y < 1.5:
            target_vx = 18.0  # Push to x=18 to bypass Pit3
            target_vy = 3.5  # Lift to y=3.5
            fx = particle_mass * 10.0 * (target_vx - vx)
            fy = particle_mass * (20.0 * (target_vy - vy) - g)  # Reduced vertical acceleration

        # Build zone: horizontal toward target and vertical if needed
        elif 6.0 <= x <= 18.0:
            target_vx = 22.0  # Push toward target zone
            fx = particle_mass * 10.0 * (target_vx - vx)
            if y < 2.5:
                target_vy = 3.0  # Lift to y=3.0
                fy = particle_mass * (20.0 * (target_vy - vy) - g)
            if y > 3.0:
                # Counteract headwind with horizontal force
                fx += 300.0  # Increased to counteract headwind

        # Target zone: no force needed

        mag = math.sqrt(fx * fx + fy * fy)
        if mag > 0:
            # Limit force per particle to 50% of the budget to avoid early exhaustion
            if used + mag <= budget:
                sandbox.apply_force_to_particle(p, fx, fy)
                used += mag
            else:
                scale = (budget - used) / mag
                if scale > 0.1:
                    sandbox.apply_force_to_particle(p, fx * scale, fy * scale)
                    used = budget
